import * as THREE from 'three';
import type { HumanLib } from './humans';
import { build, type Built, type Egg, type SceneDef } from './scenes_build';
import { disposeObject } from './scenes_props';

/**
 * Ambient scenes and easter eggs (public/data/scenes.json, generated by pipeline/scenes_build.py).
 * Scenes are built lazily: only those within `visRadius` of the player exist as objects (at most one build per frame),
 * so hundreds of scenes cost nothing. Eggs are plain data and are "found" when the player comes close.
 */
interface Entry { def: SceneDef; x: number; y: number; built: Built | null }

export class Scenes {
  readonly group = new THREE.Group();
  private entries: Entry[] = [];
  private eggs: { egg: Egg; x: number; y: number }[] = [];
  private found = new Set<string>(JSON.parse((() => { try { return localStorage.getItem('gtz-eggs') ?? '[]'; } catch { return '[]'; } })()));
  onFound: (egg: Egg, n: number, total: number) => void = () => {};

  constructor(private lib: HumanLib, private ground: (x: number, y: number) => number) {}

  async load(url = '/data/scenes.json') {
    const { scenes } = (await (await fetch(url)).json()) as { scenes: SceneDef[] };
    for (const def of scenes) {
      const x = def.x ?? def.path?.[0][0] ?? 0, y = def.y ?? def.path?.[0][1] ?? 0;
      if (def.egg) this.eggs.push({ egg: def.egg, x, y });
      if (def.type !== 'eggonly' || def.sign) this.entries.push({ def, x, y, built: null });
    }
  }

  /** Extra eggs found by proximity to data points (e.g. any city fountain). */
  addEggPoints(egg: Egg, pts: number[][]) { for (const p of pts) this.eggs.push({ egg, x: p[0], y: p[1] }); }

  get total() { return new Set(this.eggs.map((e) => e.egg.id)).size; }
  get count() { return this.found.size; }

  visRadius = 120;

  private spawn(e: Entry) {
    const b = build(e.def, { lib: this.lib, ground: this.ground });
    if (!b) return;
    e.built = b;
    if (!b.world) {
      b.obj.position.set(e.x, this.ground(e.x, e.y), -e.y);
      b.obj.rotation.y = -(e.def.dir ?? 0);
    }
    this.group.add(b.obj);
  }

  private drop(e: Entry) {
    if (!e.built) return;
    this.group.remove(e.built.obj);
    disposeObject(e.built.obj);
    e.built = null;
  }

  update(dt: number, px: number, py: number) {
    let built = 0;
    for (const e of this.entries) {
      const d = Math.hypot(e.x - px, e.y - py);
      if (!e.built) {
        if (d < this.visRadius && built < 1) { this.spawn(e); built++; }
        continue;
      }
      if (d > this.visRadius + (e.def.path ? 60 : 30)) { this.drop(e); continue; }
      const b = e.built, near = d < 60;
      if (b.world || near) b.tick?.(dt);
      if (near || b.world) {
        for (const h of b.humans) h.mixer.update(dt);
        if (b.extras) for (const x of b.extras) x.mixer.update(dt * 0.8);
      }
    }
    for (const e of this.eggs) {
      if (this.found.has(e.egg.id) || Math.hypot(e.x - px, e.y - py) > (e.egg.id === 'brunnen' ? 2.5 : 9)) continue;
      this.found.add(e.egg.id);
      try { localStorage.setItem('gtz-eggs', JSON.stringify([...this.found])); } catch { /* private mode */ }
      this.onFound(e.egg, this.found.size, this.total);
    }
  }
}
